  "impact.completed_rescues_count": { en: " completed rescues", hi: " पूर्ण बचाव", kn: " ಪೂರ್ಣಗೊಂಡ ರಕ್ಷಣೆಗಳು" },
  "impact.totaling": { en: " totaling ", hi: " कुल मात्रा ", kn: " ಒಟ್ಟು ಪ್ರಮಾಣ " },
